  b=w.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page(viewport={'width':1000,'height':700});errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.route('**/game.js',lambda r:r.fulfill(body=script,content_type='application/javascript'));p.goto('http://127.0.0.1:8788/index.html?cityArt=webgl&cityQuality=low');p.locator('#newTown').click();p.locator('#pause').click();p.locator('#panelClose').click();p.wait_for_function('window.__webglTaste&&__webglTaste.samples.length>=3');q=p.evaluate('__brushProbe()');assert q;p.locator('[data-panel=construction]').click();p.locator('[data-build=road]').scroll_into_view_if_needed();p.locator('[data-build=road]').click();beforeCamera=p.evaluate('__webglTaste.cameraInfo().position');a,z=q['points'][0],q['points'][-1];p.mouse.move(a['x'],a['y']);p.mouse.down();p.mouse.move(z['x'],z['y'],steps=8);p.mouse.up();p.wait_for_function('(cells)=>cells.every(p=>__webglTaste.tileType(p.y*128+p.x)===1)',arg=q['cells'],timeout=30000);s=p.evaluate('__cityVisualSnapshot()');assert abs(s['treasury']-(q['cash']-3*q['cost']))<.001;assert abs(s['total']-q['total'])<.001;assert p.evaluate('__webglTaste.cameraInfo().position')==beforeCamera;assert p.evaluate('__cityVisualSave()');assert not errors;result={'threeActualRoadTiles':q['cells'],'debit':3*q['cost'],'totalMoneyPreserved':True,'cameraDidNotPan':True,'graphCommitAndLiveRefresh':True,'save':True,'errors':errors};(OUT/'road-brush.json').write_text(json.dumps(result,indent=2)+'\n');print(result);b.close()
